ALTER TABLE "task_history" ADD COLUMN "cause_task_id" uuid;--> statement-breakpoint
ALTER TABLE "task_history" ADD CONSTRAINT "task_history_cause_fk" FOREIGN KEY ("tenant_id","cause_task_id") REFERENCES "public"."tasks"("tenant_id","id") ON DELETE SET NULL ("cause_task_id") ON UPDATE no action;--> statement-breakpoint
UPDATE "task_history" h SET "cause_task_id" = t."id", "text" = CASE WHEN h."kind" = 'rescheduled' THEN 'Moved because another task was rescheduled' WHEN h."kind" = 'archived' THEN 'Archived with another task' ELSE 'Restored with another task' END FROM "tasks" t WHERE t."tenant_id" = h."tenant_id" AND t."ref_no" = substring(h."text" from '^(?:Moved because|Archived with|Restored with) TSK-([0-9]+)( was rescheduled)?$')::int AND h."cause_task_id" IS NULL AND h."text" ~ '^(?:Moved because TSK-[0-9]+ was rescheduled|Archived with TSK-[0-9]+|Restored with TSK-[0-9]+)$';--> statement-breakpoint
UPDATE "task_history" SET "text" = CASE WHEN "kind" = 'rescheduled' THEN 'Moved because another task was rescheduled' WHEN "kind" = 'archived' THEN 'Archived with another task' ELSE 'Restored with another task' END WHERE "text" ~ '^(?:Moved because TSK-[0-9]+ was rescheduled|Archived with TSK-[0-9]+|Restored with TSK-[0-9]+)$';--> statement-breakpoint
UPDATE "task_history" SET "text" = 'The parent task was removed; this is now a task of its own' WHERE "kind" = 'detached' AND "text" ~ '^TSK-[0-9]+ was removed; this is now a task of its own$';
